from __future__ import annotations

import re
from typing import Any

from marshmallow import EXCLUDE, Schema, ValidationError, fields


_USERNAME_RE = re.compile(r"^[A-Za-z0-9]+$")


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE  # drop unknown keys

    username = fields.String(required=True)
    email = fields.Email(required=True)

    plan = fields.String(
        required=False,
        load_default="free",
    )
    age = fields.Integer(required=False, load_default=fields.missing)

    # Validate plan
    def _validate_plan(self, value: str) -> None:
        if value not in {"free", "pro", "team"}:
            raise ValidationError("Must be one of: free, pro, team.", field_name="plan")

    @staticmethod
    def _validate_username(value: str) -> None:
        if not _USERNAME_RE.match(value or ""):
            raise ValidationError("Username must be alphanumeric.", field_name="username")

    # Wire custom validators using marshmallow's hooks
    def _deserialize(self, value: Any, attr: str, data: Any, **kwargs):
        return super()._deserialize(value, attr, data, **kwargs)

    # username validator
    @fields.validates("username")
    def validates_username(self, value: str) -> None:
        self._validate_username(value)

    # plan validator
    @fields.validates("plan")
    def validates_plan(self, value: str) -> None:
        self._validate_plan(value)

    # age validator
    @fields.validates("age")
    def validates_age(self, value: int) -> None:
        if value is None:
            return
        if not (16 <= int(value) <= 120):
            raise ValidationError("Age must be between 16 and 120.", field_name="age")


class SignupValidationError(ValueError):
    """ValueError subclass carrying structured field->messages errors."""

    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("invalid signup data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """Validate and clean sign-up input.

    Required:
      - username: alphanumeric string
      - email: valid email address
    Optional:
      - plan: one of {"free","pro","team"} (default "free")
      - age: integer in [16, 120]
    Unknown keys are dropped.

    Returns the cleaned dict.
    Raises:
      ValueError with attribute `messages` mapping field->list of error messages.
    """
    try:
        cleaned = _SignupSchema().load(data)
    except ValidationError as err:
        # marshmallow gives {field: [msg, ...], ...}; ensure we always have lists of strings
        messages: dict[str, list[str]] = {}
        for field, msgs in (err.messages or {}).items():
            if isinstance(msgs, list):
                messages[field] = [str(m) for m in msgs]
            else:
                messages[field] = [str(msgs)]
        raise SignupValidationError(messages) from None

    # Ensure defaults for omitted optional fields are present as per schema output.
    # (marshmallow will already fill plan load_default="free")
    return cleaned

from __future__ import annotations

from typing import Any


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each provided distribution name (keyed exactly as given) to the installed
    distribution version string (case-insensitive match), or None if not installed.

    Example:
        dependency_report(["Requests", "nonexistent"]) == {
            "Requests": "2.32.3",
            "nonexistent": None,
        }
    """
    try:
        # Prefer the project's runtime helper if available.
        from pkg_info import installed_version as _installed_version
    except Exception:  # pragma: no cover
        _installed_version = None  # type: ignore[assignment]

    if _installed_version is None:
        import importlib.metadata as importlib_metadata

        def _installed_version(dist_name: str) -> str | None:
            try:
                return importlib_metadata.version(dist_name)
            except importlib_metadata.PackageNotFoundError:
                return None

    report: dict[str, str | None] = {}
    for n in names:
        report[n] = _installed_version(n)
    return report

