import httpx

from api_fetch import iter_items


def open_ticket_titles(client: httpx.Client, project: str) -> list[str]:
    """Fetch all open ticket titles for a project, following pagination in `next`.

    The server requires `status` and `project` on every page request.
    """
    params = {"status": "open", "project": project}
    titles: list[str] = []
    for item in iter_items(client, "/tickets", params=params):
        # Expected shape: {"title": ...}
        titles.append(item["title"])
    return titles

