import re
from email.utils import parseaddr
from typing import Any


class SignupError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("invalid signup data")
        self.messages = messages


_EMAIL_RE = re.compile(
    # Reasonable RFC-ish pattern (not fully RFC 5322, but good for typical APIs)
    r"^(?P<local>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)"
    r"@(?P<domain>(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,63}|[A-Za-z0-9-]{1,63}))$"
)


def _is_valid_email(value: Any) -> bool:
    if not isinstance(value, str) or not value:
        return False
    # parseaddr helps catch some malformed strings, regex does the rest.
    parsed_name, parsed_email = parseaddr(value)
    if not parsed_email or parsed_email != value:
        return False
    return bool(_EMAIL_RE.match(value))


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup payload.

    Required: username (alphanumeric string), email (valid email)
    Optional: plan (default "free"; one of "free", "pro", "team")
              age (integer 16..120 inclusive)
    Unknown keys are dropped.

    Returns cleaned dict with defaults applied.
    Raises ValueError (with .messages dict mapping field -> [messages]) on invalid input.
    """
    if not isinstance(data, dict):
        raise SignupError({"__all__": ["Input must be an object."]})

    cleaned: dict[str, Any] = {}
    messages: dict[str, list[str]] = {}

    def add_error(field: str, msg: str) -> None:
        messages.setdefault(field, []).append(msg)

    # username
    if "username" not in data:
        add_error("username", "Missing data for required field.")
    else:
        username = data.get("username")
        if not isinstance(username, str) or not username or not username.isalnum():
            add_error("username", "Must be an alphanumeric string.")

    # email
    if "email" not in data:
        add_error("email", "Missing data for required field.")
    else:
        email = data.get("email")
        if not _is_valid_email(email):
            add_error("email", "Not a valid email address.")

    # plan (optional, default free)
    plan = data.get("plan", "free")
    if plan is None:
        plan = "free"
    if not isinstance(plan, str):
        add_error("plan", 'Must be one of "free", "pro", "team".')
    else:
        allowed_plans = {"free", "pro", "team"}
        if plan not in allowed_plans:
            add_error("plan", 'Must be one of "free", "pro", "team".')

    # age (optional)
    if "age" in data and data.get("age") is not None:
        age = data.get("age")
        # bool is a subclass of int; disallow explicitly
        if isinstance(age, bool) or not isinstance(age, int):
            add_error("age", "Must be an integer.")
        else:
            if not (16 <= age <= 120):
                add_error("age", "Must be between 16 and 120 inclusive.")

    if messages:
        raise SignupError(messages)

    # Build cleaned output (dropping unknown keys)
    cleaned["username"] = data["username"]
    cleaned["email"] = data["email"]
    cleaned["plan"] = plan
    if "age" in data and data.get("age") is not None:
        cleaned["age"] = data["age"]

    return cleaned
